function performUpkeep() external {
    uint256 gasStart = gasleft();
    uint256 processed = 0;
    uint256 currentTick = getCurrentTick();

    while (
        hasOrdersAtTick(currentTick) && 
        gasleft() > MIN_GAS_RESERVE && 
        processed < MAX_ORDERS_PER_UPKEEP
    ) {
        Order memory order = getNextOrder(currentTick);

        // Estimate gas for order fulfillment
        uint256 gasBeforeOrder = gasleft();
        if (gasBeforeOrder < estimateOrderGas(order) + MIN_GAS_RESERVE) {
            break; // Not enough gas for this order
        }

        _fulfillOrder(order);
        processed++;
        currentTick = getNextTickWithOrders(currentTick);
    }

    emit UpkeepPerformed(processed, gasStart - gasleft());
}
