function _isValidTransition(ProtocolState from, ProtocolState to) internal pure returns (bool) {
    if (from == ProtocolState.INACTIVE) {
        return to == ProtocolState.ACTIVE;
    } else if (from == ProtocolState.ACTIVE) {
        return to == ProtocolState.PAUSED || to == ProtocolState.EMERGENCY;
    } else if (from == ProtocolState.PAUSED) {
        return to == ProtocolState.ACTIVE || to == ProtocolState.EMERGENCY;
    } else if (from == ProtocolState.EMERGENCY) {
        return to == ProtocolState.INACTIVE;
    }
    return false;
